/**
 * Smart trigger detection utilities for prompting agent to use memory tools.
 */
// Track recent nudges to avoid spam
const recentNudges = new Map();
const NUDGE_COOLDOWN_MS = 5 * 60 * 1000; // 5 minutes cooldown per trigger type
const CODE_SEARCH_GUIDANCE = ' Also consider code_search first; if you need to confirm code-index readiness, check project_status(action: "list").';
function shouldTrigger(sessionID, type) {
    const key = `${sessionID}:${type}`;
    const lastNudge = recentNudges.get(key);
    if (!lastNudge)
        return true;
    const elapsed = Date.now() - lastNudge.timestamp;
    return elapsed > NUDGE_COOLDOWN_MS;
}
function recordNudge(sessionID, type) {
    const key = `${sessionID}:${type}`;
    recentNudges.set(key, { type, timestamp: Date.now() });
}
function withCodeSearchGuidance(message, shouldAdd) {
    return shouldAdd ? `${message}${CODE_SEARCH_GUIDANCE}` : message;
}
/**
 * Detect if text contains architectural decisions or choices.
 */
function detectDecisionPoint(text) {
    const patterns = [
        /\b(decide|decided|choose|chose|go with|settled on|opt for|will use)\b/i,
        /\b(architecture|approach|strategy|solution)\s+(?:is|will be|should be)\b/i,
        /(?:决定|选择|方案|采用)\s*(?:使用|选择|采用)/,
        /\b(let's|we should|I will)\s+(?:use|go with|implement|choose)\b/i,
        /\b(better to|prefer|recommend)\s+(?:use|go with)\b/i,
    ];
    return patterns.some((p) => p.test(text));
}
/**
 * Detect if text indicates starting a new task or feature.
 */
function detectNewTaskIntent(text) {
    const patterns = [
        /\b(implement|build|develop|set up)\s+(?:a\s+|an?\s+|the\s+)?(?:new\s+)?\w{4,}/i,
        /\b(let's|please|can you)\s+(implement|create|build|develop)\b/i,
        /\b(start|begin)\s+(?:working\s+)?(?:on\s+)?(?:the|a|new)?\s*(?:task|feature|project|component|module|service)\b/i,
        /\bcreate\s+(?:a\s+|an?\s+|the\s+)(?:new\s+)?\w{4,}/i,
    ];
    return patterns.some((p) => p.test(text));
}
/**
 * Detect if messages contain error or debugging context.
 */
function detectErrorContext(text) {
    const patterns = [
        /\b(error|exception|crash|bug)\b/i,
        /\b(fail|failed)\s+(?:to|when|with|on|during)\b/i,
        /\b(debug|troubleshoot)\s+(?:the|this|a|an)\b/i,
        /\b(not working|doesn't work|is broken|is crashing)\b/i,
        /\b(stack trace|error message|exception thrown|traceback)\b/i,
    ];
    return patterns.some((p) => p.test(text));
}
/**
 * Detect if text is asking about local code structure, callers, or definitions.
 */
function detectCodeExploration(text) {
    const codeLikeSignals = [
        /\b[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*\b/,
        /\b[A-Za-z_][A-Za-z0-9_]*[A-Z][A-Za-z0-9_]*\b/,
        /\b[A-Za-z_][A-Za-z0-9_]*_[A-Za-z0-9_]+\b/,
        /\b(?:config|loader|loading|hook|trigger|helper|function|module|service|class|method|store|index|api|implementation)\b/i,
    ];
    const hasCodeLikeSignal = codeLikeSignals.some((p) => p.test(text));
    const chineseLocalCodePatterns = [
        /(?:这个功能怎么实现的|这个功能是怎么实现的|这个怎么实现的|怎么实现的)/,
        /(?:谁调用\s*[A-Za-z_][\w.]*|在哪里定义\s*[A-Za-z_][\w.]*|谁调用\s*\w|在哪里定义\s*\w)/,
        /(?:这个|这段|这个项目|这个模块|这个配置|本地代码|本地项目).{0,16}(?:怎么|如何).{0,12}(?:触发|调用|定义|实现|工作|运行)/,
        /(?:项目里|项目中|代码里|本地代码里|本地项目里).{0,16}(?:触发|调用|定义|实现|工作原理|怎么走)/,
    ];
    if (chineseLocalCodePatterns.some((p) => p.test(text))) {
        return true;
    }
    const patterns = [
        /\b(where is|where are|who calls|what calls|trace callers of|refactor impact for)\b.*\b[A-Za-z_][\w.]*\b/i,
        /\b(?:where is|where are|who calls|what calls|trace callers of|refactor impact for)\s+[A-Za-z_][\w.]*\b/i,
        /\b(?:how does|how do)\s+(?:the\s+)?(?:config|loader|loading|hook|trigger|helper|function|module|service|class|method|store|index|api|implementation)\b/i,
        /\b(?:how does|how do)\s+[^?]{0,80}\b(?:config|loader|loading|hook|trigger|helper|function|module|service|class|method|store|index|api|implementation)\b/i,
        /\b(?:in this project|in the repo|in this codebase|locally|local code|this module|this file|this config)\b.*\b(?:where is|where are|who calls|what calls|how does|how do|defined|implemented|triggered)\b/i,
        /\b(?:where is|where are|who calls|what calls|how does|how do|defined|implemented|triggered)\b.*\b(?:in this project|in the repo|in this codebase|locally|local code|this module|this file|this config)\b/i,
    ];
    return hasCodeLikeSignal && patterns.some((p) => p.test(text));
}
/**
 * Check all triggers and return the highest priority nudge.
 * Priority: decision > new_task > error_context > code_exploration
 */
export function checkTriggers(sessionID, agentText, userText) {
    const addCodeSearchGuidance = detectCodeExploration(userText);
    // Check decision trigger (highest priority)
    if (detectDecisionPoint(agentText) && shouldTrigger(sessionID, "decision")) {
        recordNudge(sessionID, "decision");
        return {
            triggered: true,
            type: "decision",
            message: withCodeSearchGuidance("[MEMORY NUDGE] 💡 You just made a decision. Consider storing it with memory_save using the DECISION prefix — include alternatives you considered.", addCodeSearchGuidance),
        };
    }
    // Check new task trigger
    if (detectNewTaskIntent(userText) && shouldTrigger(sessionID, "new_task")) {
        recordNudge(sessionID, "new_task");
        return {
            triggered: true,
            type: "new_task",
            message: withCodeSearchGuidance("[MEMORY NUDGE] 🚀 Starting a new task? Consider calling memory_query to find relevant context and past decisions first.", addCodeSearchGuidance),
        };
    }
    // Check error context trigger
    if (detectErrorContext(userText) && shouldTrigger(sessionID, "error")) {
        recordNudge(sessionID, "error");
        return {
            triggered: true,
            type: "error_context",
            message: withCodeSearchGuidance("[MEMORY NUDGE] 🔍 An error was mentioned. Consider searching memory for BUGFIX entries before debugging.", addCodeSearchGuidance),
        };
    }
    // Check code exploration trigger (lowest priority)
    if (detectCodeExploration(userText) &&
        shouldTrigger(sessionID, "code_exploration")) {
        recordNudge(sessionID, "code_exploration");
        return {
            triggered: true,
            type: "code_exploration",
            message: '[MEMORY NUDGE] 🔎 This looks like a local code question. Consider using code_search first; if you need to confirm code-index readiness, check project_status(action: "list") before deciding whether to index.',
        };
    }
    return { triggered: false, type: null, message: "" };
}
/**
 * Clear nudge history for a session (e.g., after compaction).
 */
export function clearNudgeHistory(sessionID) {
    for (const key of recentNudges.keys()) {
        if (key.startsWith(`${sessionID}:`)) {
            recentNudges.delete(key);
        }
    }
}
